class Solution:
    def maxDistToClosest(self, seats: list[int]) -> int:
        n = len(seats)
        prev = -1
        ans = 0
        for i in range(n):
            if seats[i] == 1:
                if prev == -1:
                    ans = i
                else:
                    ans = max(ans, (i - prev) // 2)
                prev = i
        ans = max(ans, n - 1 - prev)
        return ans

